type ControllerV1 struct {
	service       *sse.Service
	conversations conversation.ConversationStore
	coordinator   *conversation.Coordinator
	loops         *conversation.TurnLoopRegistry
	limiter       *conversation.RunLimiter
	locker        conversation.ConversationLocker
	runtime       *chat_pipeline.Runtime
}

func appendTurn(ctx context.Context, store conversation.ConversationStore, key conversation.SessionKey, idempotencyKey string, userMessage, assistantMessage *schema.Message) error {
	if idempotencyKey == "" {
		return store.Append(ctx, key, userMessage, assistantMessage)
	}
	idempotent, ok := store.(conversation.IdempotentConversationStore)
	if !ok {
		return errors.New("conversation store does not support idempotency keys")
	}
	_, err := idempotent.AppendIdempotent(ctx, key, idempotencyKey, userMessage, assistantMessage)
	return err
}

func NewV1(runtime *chat_pipeline.Runtime) chat.IChatV1 {
	return NewV1WithStore(runtime, nil)
}

// NewV1WithStore allows deployment wiring to select a durable conversation
// store. A nil store retains the development-friendly memory implementation.
func NewV1WithStore(runtime *chat_pipeline.Runtime, store conversation.ConversationStore) chat.IChatV1 {
	return NewV1WithStoreAndLocker(runtime, store, nil)
}

func NewV1WithStoreAndLocker(runtime *chat_pipeline.Runtime, store conversation.ConversationStore, locker conversation.ConversationLocker) chat.IChatV1 {
	if store == nil {
		store = conversation.NewMemoryStore(6)
	}
	return &ControllerV1{
		service:       sse.New(),
		conversations: store,
		coordinator:   conversation.NewCoordinator(),
		loops:         conversation.NewTurnLoopRegistryWithIdle(128, 30*time.Minute),
		limiter:       conversation.NewRunLimiter(100),
		locker:        locker,
		runtime:       runtime,
	}
}

func (c *ControllerV1) lockTurn(ctx context.Context, key conversation.SessionKey) (context.Context, func(), error) {
	if c.locker == nil {
		return ctx, func() {}, nil
	}
	lockCtx, cancel := context.WithCancel(ctx)
	lease, err := c.locker.Lock(lockCtx, key)
	if err != nil {
		cancel()
		return nil, nil, err
	}
	renewalDone := lease.StartRenewal(lockCtx)
	go func() {
		if renewalErr, ok := <-renewalDone; ok && renewalErr != nil {
			cancel()
		}
	}()
	var once sync.Once
	return lockCtx, func() {
		once.Do(func() {
			cancel()
			_ = lease.Unlock(context.Background())
		})
	}, nil
}

func (c *ControllerV1) turnSession(ctx context.Context, key conversation.SessionKey) (*conversation.TurnLoopSession, error) {
	if c.runtime == nil || c.runtime.ADKAgent == nil {
		return nil, errors.New("chat agent runtime is not initialized")
	}
	return c.loops.GetOrCreate(ctx, key, func(context.Context) (adk.Agent, error) {
		return c.runtime.ADKAgent, nil
	})
}

func (c *ControllerV1) buildTurnInput(ctx context.Context, key conversation.SessionKey, question string) (*adk.AgentInput, error) {
	history, _, err := c.conversations.Load(ctx, key)
	if err != nil {
		return nil, err
	}
	messages := make([]*schema.Message, 0, len(history)+1)
	messages = append(messages, history...)
	messages = append(messages, schema.UserMessage(question))
	return &adk.AgentInput{Messages: messages}, nil
}

func (c *ControllerV1) Close(ctx context.Context) error {
	if c.loops == nil {
		if c.limiter != nil {
			c.limiter.Close()
		}
		return nil
	}
	if c.limiter != nil {
		c.limiter.Close()
	}
	return c.loops.StopAll(ctx)
}
